beforeExample:
package test;
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.IAdaptable;

public class TestClass {
    public IResource getResourceAdapter(IAdaptable element) {
        if (element != null) {
            IResource resource = element.getAdapter(IResource.class);
            return resource;
        }
        return null;
    }
}

afterExample:
package test;
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.IAdaptable;
import org.eclipse.core.runtime.Adapters;

public class TestClass {
    public IResource getResourceAdapter(IAdaptable element) {
        if (element != null) {
            IResource resource = Adapters.adapt(element, IResource.class);
            return resource;
        }
        return null;
    }
}

negativeExample:
package test;
import org.eclipse.core.runtime.IAdaptable;

public class TestClass {
    // Not calling getAdapter
    public Object someOtherMethod(IAdaptable element) {
        return element.toString();
    }

    // Not an IAdaptable type for $element, so the guard will prevent matching
    public Object getAdapterFromObject(Object obj) {
        // This pattern will not match because 'obj' is not of type IAdaptable
        // The rule is designed to apply when $element is statically known as IAdaptable
        return ""; 
    }
}
